const fs = require('fs');
const lines = fs.readFileSync('videos/light-frames/report.txt','utf8').split(/\r?\n/);
const rows = [];
for (const line of lines) {
  const m = line.match(/^\s*(\d+)\s+\S+\s+\S+\s+[\d.]+\s+[\d.]+\s+[\d.]+\s+[\d.]+\s+(\d+)-(\d+)\s+(\d+)-(\d+)\s+(\d+)\s+(\d+)/);
  if (m) {
    const [, idx, l, r, t, b] = m;
    rows[Number(idx)] = { l: Number(l), r: Number(r), t: Number(t), b: Number(b) };
  }
}
console.log('parsed frames:', rows.filter(Boolean).length);

// Bad/unreliable frames to exclude from smoothing input
const BAD = new Set([153, 155]);
const N = 192;
const raw = rows.map((r, i) => (r && !BAD.has(i)) ? r : null);

// Moving average window +-3, skipping nulls
function smooth(i, key) {
  let sum = 0, n = 0;
  for (let j = Math.max(0, i - 3); j <= Math.min(N - 1, i + 3); j++) {
    if (raw[j]) { sum += raw[j][key]; n++; }
  }
  return n ? sum / n : null;
}

const SETTLE = 129; // book fully open and still from here on; later frames just have a light sweep confusing edge detection
const table = [];
let settleVal = null;
for (let i = 0; i < N; i++) {
  if (i <= SETTLE) {
    table[i] = { l: smooth(i,'l'), r: smooth(i,'r'), t: smooth(i,'t'), b: smooth(i,'b') };
    if (i === SETTLE) settleVal = table[i];
  } else {
    table[i] = settleVal;
  }
}

