512	      return;
513	    }
514	    const target = targetScroll();
515	    const dt = last ? Math.min(now - last, 50) / 1000 : 1 / 60;
516	    if (pos === null || reduceMotion.matches || !glide) {
517	      pos = target;
518	    } else {
519	      pos += (target - pos) * (1 - Math.exp(-dt / glide));
520	      if (Math.abs(target - pos) < 0.0005) pos = target;
521	    }
522	    sharpen = pos === target ? Math.min(1, sharpen + dt / SHARPEN) : Math.max(0, sharpen - (3 * dt) / SHARPEN);
523	    last = pos === target && sharpen === 1 ? 0 : now;
524	    paint();
525	    if (moving !== (pos !== target)) {
526	      moving = pos !== target;
527	      hero.dispatchEvent(new Event(moving ? 'bookmove' : 'bookrest'));
528	    }
529	    if (last) schedule();
530	  }
531	
532	  // Updates the headline and aayat, and redraws the book only when its frame, the size or the loaded
533	  // frames have changed. Under reduced motion the book is shown open and the headline stays.
534	  function paint() {
535	    if (pos === null) return;
536	    const still = reduceMotion.matches;
537	    const exact = frameAt(pos);
538	    const whole = Math.round(exact);
539	    const frame = still ? LAST : blend ? exact + (whole - exact) * smoothstep(sharpen) : whole;
540	    if (pos !== painted || dirty) {
541	      const rest = still ? 1 : 1 - clamp(frame / NAME_GONE);
542	      for (const part of resting) part.style.opacity = rest;
543	      showAayat(pos, still);
544	      endAt(pos);
545	      painted = pos;
546	    }
547	    if (frame !== drawn || dirty) {
548	      if (draw(frame)) {
549	        drawn = frame;
550	        dirty = false;
551	      }
552	    }
553	  }
554	
555	  function resize() {
556	    const width = canvas.clientWidth;
557	    const height = canvas.clientHeight;
558	    const dpr = Math.min(devicePixelRatio || 1, 2);
559	    canvas.width = Math.round(width * dpr);
560	    canvas.height = Math.round(height * dpr);
561	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
562	    ctx.imageSmoothingQuality = 'high';
563	    // One size for the whole opening: the open book always fits, and the 720p footage is
564	    // never stretched past its own size.
565	    scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / (OPEN_RIGHT - BOOK_LEFT), 1);
566	    place();
567	    fitHint();
568	    fit();
569	    dirty = true;
570	    paint(); // draw now: resizing the canvas has just cleared it
571	    schedule(); // the hero's height follows the window, so the scroll position may now mean a different frame
572	  }
573	
574	  // Reduced motion: no scrubbing, just the open book, and only its frame is loaded.
575	  function applyMotion() {
576	    document.documentElement.classList.toggle('still', reduceMotion.matches);
577	    if (light()) loadIvory(); // the frames wait until the page turns dark
578	    else if (reduceMotion.matches) load(LAST);
579	    else loadAll();
580	    dirty = true;
581	    schedule();
582	  }
583	
584	  // Light and dark ----------------------------------------------------------------------------
585	  // The switch at the end of the top bar. The choice is remembered on this device (index.html applies it before the
586	  // page draws). Where the browser can, the whole page cross-fades from one to the other.
587	
588	  function applyTheme() {
589	    const isLight = light();
590	    themeButton.setAttribute('aria-label', isLight ? 'Switch to dark mode' : 'Switch to light mode');
591	    themeButton.querySelector('.words').textContent = isLight ? themeButton.dataset.toDark : themeButton.dataset.toLight;
592	    themeColor.content = isLight ? '#F5F4F1' : '#1F1A18';
593	    applyMotion();
594	  }
595	
596	  themeButton.addEventListener('click', () => {
597	    // The book's screen changes height, so the visitor would land somewhere else (the user, 2026-09-14: half the book
598	    // showing). Unless at the very top, the ending's top stays where it is in the window, no lower than under a whole
599	    // book, and the lock-in then settles on the nearest resting place.
600	    const ending = Math.min(close.getBoundingClientRect().top, stage.offsetHeight);
601	    const atTop = scrollY < 1;
602	    const turn = () => {
603	      const theme = light() ? 'dark' : 'light';
604	      document.documentElement.dataset.theme = theme;
605	      try {
606	        localStorage.setItem('theme', theme);
607	      } catch {
608	        // a private window can refuse; the switch still works for this visit
609	      }
610	      applyTheme();
611	      takeOver();
612	      if (!atTop) scrollBy(0, close.getBoundingClientRect().top - ending);
613	      lastY = scrollY;
614	      pos = targetScroll(); // jump the book to where the page now is
615	      paint(); // draw now, so the cross-fade ends on the new book
616	      waitToFinish();
617	    };
618	    // The cross-fade waits for the page to draw, so a page that isn't showing just changes. The browser can still cancel
619	    // a cross-fade part way; the theme changes all the same, so its promises are allowed to fail quietly.
620	    if (!document.startViewTransition || reduceMotion.matches || document.visibilityState !== 'visible') return turn();
621	    const fade = document.startViewTransition(turn);
622	    Promise.allSettled([fade.ready, fade.updateCallbackDone, fade.finished]);
623	  });
624	
625	  // TRYOUT --------------------------------------------------------------------------
626	  // Options shown only on this PC or a phone on the same wifi. Once the user picks: put the picks in the
627	  // settings above and in styles.css, then delete this block, the TRYOUT part of styles.css and the
628	  // unused Arabic font in index.html.
629	
630	  if (/^(localhost|[\d.]+)$/.test(location.hostname)) {
631	    const narrow = matchMedia('(max-width: 767px)').matches;
632	    const panel = document.createElement('details');
633	    panel.className = 'tryout';
634	    panel.open = !narrow; // closed to start with on phones, where it would cover the book
635	    panel.innerHTML = '<summary>Options</summary>';
636	    document.body.append(panel);
637	
638	    // Groups of rows, each under a heading that opens and closes. Rows go into the group named last, and naming a
639	    // group again adds to it. atmosphere.js and ending-options.js use this too; `first` puts a new group at the top.
640	    let group = panel;
641	    window.tryoutGroup = (title, { open = false, first = false } = {}) => {
642	      group = [...panel.querySelectorAll(':scope > details')].find((g) => g.dataset.title === title);
643	      if (group) return;
644	      group = document.createElement('details');
645	      group.dataset.title = title;
646	      group.open = open;
647	      group.append(el('summary', '', title));
648	      if (first) panel.querySelector('summary').after(group);
649	      else panel.append(group);
650	    };
651	
652	    // A row of buttons; the one matching `initial` starts pressed. atmosphere.js adds its rows with this too.
653	    window.addOption = (label, choices, initial, pick) => {
654	      const row = document.createElement('div');
655	      row.append(el('span', '', label));
656	      for (const [text, value] of Object.entries(choices)) {
657	        const b = el('button', '', text);
658	        b.type = 'button';
659	        b.setAttribute('aria-pressed', value === initial);
660	        b.addEventListener('click', () => {
661	          for (const other of row.querySelectorAll('button')) other.setAttribute('aria-pressed', other === b);
662	          pick(value);
663	        });
664	        row.append(b);
665	      }
666	      group.append(row);
667	    };
668	
669	    // A slider with its value shown beside it, in the words `format` gives.
670	    window.addSlider = (label, min, max, step, initial, format, pick) => {
671	      const row = document.createElement('div');
672	      const range = el('input', '');
673	      Object.assign(range, { type: 'range', min, max, step, value: initial });
674	      range.setAttribute('aria-label', label);
675	      const shown = el('output', '', format(initial));
676	      range.addEventListener('input', () => {
677	        const value = Number(range.value);
678	        shown.textContent = format(value);
679	        pick(value);
680	      });
681	      row.append(el('span', '', label), range, shown);
682	      group.append(row);
683	    };
684	
685	    // A free-text field: typing updates the page as you go. wordmark-options.js and ending-options.js use this for
686	    // the headline, the sentence under it, the closing line, the button words and the name at the very end, so any
687	    // of them can be typed exactly as wanted, not only chosen from a preset. Returns the input, so a preset button
688	    // can fill it in too and the field always shows what the page currently says.
689	    window.addText = (label, initial, pick) => {
690	      const row = document.createElement('div');
691	      const field = el('input', '');
692	      Object.assign(field, { type: 'text', value: initial });
693	      field.setAttribute('aria-label', label);
694	      field.addEventListener('input', () => pick(field.value));
695	      row.append(el('span', '', label), field);
696	      group.append(row);
697	      return field;
698	    };
699	
700	    const redraw = () => {
701	      dirty = true;
702	      schedule();
703	    };
704	    const retime = (set) => (value) => {
705	      set(value);
706	      redraw();
707	    };
708	    const setData = (key) => (value) => {
709	      document.documentElement.dataset[key] = value;
710	      fit();
711	    };
712	    tryoutGroup('Ending', { open: true, first: true });
713	    addOption('Scroll once it opens', { 'As before': 1.4, Less: 0.7, Least: 0.35 }, hold, (v) => {
714	      hold = v;
715	      applyTimeline();
716	      redraw();
717	    });
718	    addOption('Ending locks into place', { Yes: true, No: false }, lockEnding, (v) => (lockEnding = v));
719	    addSlider('Wait before gliding', 0, 400, 10, finishWait, (v) => `${v} ms`, (v) => (finishWait = v));
720	    addOption('Glide start', { 'Already moving': 'moving', 'Gently (before)': 'gentle' }, glideStart, (v) => (glideStart = v));
721	    tryoutGroup('Opening and aayat');
722	    const glideText = (v) => (v ? `${v.toFixed(2)} s${v === 0.28 ? ' (your pick)' : ''}` : 'Off');
723	    addSlider('Opening glide', 0, 0.5, 0.01, glide, glideText, retime((v) => (glide = v)));
724	    addOption('Blend frames', { Off: false, On: true }, blend, retime((v) => (blend = v)));
725	    addOption('Half-open book', { Stays: 'off', 'Nearer end': 'nearest', 'Way you scrolled': 'direction' }, finish, (v) => (finish = v));
726	    addSlider('Auto open/close speed', 25, 300, 5, finishSpeed * 100, (v) => `${v}%`, (v) => (finishSpeed = v / 100));
727	    addOption('Arabic lettering', { 'Amiri Quran': 'amiri', Scheherazade: 'scheherazade' }, 'amiri', setData('arabic'));
728	    addOption('Left page', { 'Surah name': 'name', 'English meaning': 'meaning' }, 'name', setData('left'));
729	    if (narrow) {
730	      const phoneScroll = setData('phoneScroll');
731	      phoneScroll('short');
732	      addOption('Scroll length', { Long: 'long', Medium: 'medium', Short: 'short' }, 'short', (v) => {
733	        phoneScroll(v);
734	        redraw();
735	      });
736	      addOption('Surah name', { 'Under the book': 'under', 'On the page': 'page' }, 'under', setData('phoneLeft'));
737	    }
738	  }
739	
740	  // Finishing the opening ------------------------------------------------------------
741	
742	  function onScroll() {
743	    schedule();
744	    placeTopbar();
745	    if (autoScroll) return; // the page's own scrolling
746	    direction = Math.sign(scrollY - lastY) || direction;
747	    lastY = scrollY;
748	    waitToFinish();
749	  }
750	
751	  function waitToFinish() {
752	    clearTimeout(finishTimer);
753	    finishTimer = setTimeout(finishOpening, finishWait);
754	  }
755	
756	  function finishOpening() {
757	    if (touching || autoScroll || reduceMotion.matches) return;
758	    if (lockEnding && settleEnding()) return;
759	    if (finish === 'off' || !visible || light()) return;
760	    const progress = (targetScroll() - REST) / OPEN;
761	    if (progress <= 0.002 || progress >= 0.998) return; // closed or open already
762	    const open = finish === 'nearest' ? progress >= 0.5 : direction > 0;
763	    scrollToScreens(open ? REST + OPEN : REST);
764	  }
765	
766	  // Around the ending the page never rests part way (the user, 2026-09-14: it should "lock in", without a fight). It has
767	  // three resting places, given as where the ending's top is in the window: under the open book's whole screen (that
768	  // screen's height), filling the screen (0), and scrolled away with the footer's top at the top of the window (minus its
769	  // own height). Stopped between two of them, the page carries on to the one the visitor was heading for ("Nearer end":
770	  // the nearer one), so the book glides up and the ending settles into the screen. Past the last, the footer scrolls
771	  // freely. Like the half-open book, it waits for scrolling to stop, and any wheel, key, click or touch takes over.
772	  // Returns whether it moved.
773	  function settleEnding() {
774	    if (under()) return false; // there the ending shares the book's screen
775	    const top = close.getBoundingClientRect().top;
776	    const stops = [stage.offsetHeight, 0, -close.offsetHeight];
777	    for (let k = 0; k < 2; k++) {
778	      const above = stops[k];
779	      const below = stops[k + 1];
780	      if (top >= above - 1 || top <= below + 1) continue;
781	      const down = finish === 'nearest' ? top - below < above - top : direction > 0;
782	      const y = Math.min(scrollY + top - (down ? below : above), document.documentElement.scrollHeight - innerHeight);
783	      if (Math.abs(y - scrollY) < 1) return false; // the page doesn't go any further
784	      scrollToY(y);
785	      return true;
786	    }
787	    return false;
788	  }
789	
790	  // Scrolls the page to a point on the hero's timeline.
791	  function scrollToScreens(s) {
792	    const range = hero.offsetHeight - stage.offsetHeight;
793	    scrollToY(hero.getBoundingClientRect().top + scrollY + (s / total) * range);
794	  }
795	
796	  // Scrolls the page to y at `speed` screens a second, starting already moving, or gently from still.
797	  let autoDir = 0; // which way the page's own scrolling is going
798	  function scrollToY(y, speed = finishSpeed, gentle = glideStart === 'gentle') {
799	    cancelAnimationFrame(autoScroll);
800	    const from = scrollY;
801	    const distance = y - from;
802	    autoDir = Math.sign(distance);
803	    const duration = Math.max(300, (1000 * Math.abs(distance)) / innerHeight / speed); // a short finish still eases
804	    const start = performance.now();
805	    const tick = (now) => {
806	      const t = Math.min(1, (now - start) / duration);
807	      const eased = !gentle ? Math.sin((t * Math.PI) / 2) : t < 0.5 ? 4 * t * t * t : 1 - (2 - 2 * t) ** 3 / 2;
808	      scrollTo(0, from + distance * eased);
809	      autoScroll = t < 1 ? requestAnimationFrame(tick) : 0;
810	      if (!autoScroll) lastY = scrollY;
811	    };
812	    autoScroll = requestAnimationFrame(tick);
813	  }
814	
815	  // Any scrolling by the visitor takes over from the page's own.
816	  function takeOver() {
817	    cancelAnimationFrame(autoScroll);
818	    autoScroll = 0;
819	    lastY = scrollY;
820	    tabFrom = null;
821	  }
822	
823	  addEventListener('scroll', onScroll, { passive: true });
824	  for (const type of ['keydown', 'mousedown']) addEventListener(type, takeOver, { passive: true });
825	  // A wheel turned the way the page is already going doesn't stop it: stopping there felt stuck (the user, 2026-09-14).
826	  addEventListener('wheel', (e) => (autoScroll && Math.sign(e.deltaY) === autoDir) || takeOver(), { passive: true });
827	
828	  // Tab from the top bar lands on the ending's buttons, and the browser jumps there past the opening (the user,
829	  // 2026-09-14). Instead the page glides there through the book, quickly. Arrows, Space and Page Down scrub as always.
830	  let tabFrom = null; // where the page was when Tab was pressed
831	  addEventListener('keydown', (e) => e.key === 'Tab' && (tabFrom = scrollY));
832	  addEventListener('focusin', (e) => {
833	    const from = tabFrom;
834	    tabFrom = null;
835	    if (from === null || reduceMotion.matches || light()) return;
836	    const glide = () => {
837	      const end = hero.getBoundingClientRect().top + scrollY + hero.offsetHeight - stage.offsetHeight; // book fully open
838	      if (from >= end - 1 || scrollY <= end) return false; // already past the opening, or the jump didn't cross it
839	      const to = close.contains(e.target) ? scrollY + close.getBoundingClientRect().top : scrollY;
840	      scrollTo(0, from);
841	      scrollToY(to, TAB_SPEED, true);
842	      return true;
843	    };
844	    // Chrome has already jumped by now; a browser that jumps after this event is caught before the next frame is drawn.
845	    if (!glide()) requestAnimationFrame(glide);
846	  });
847	  addEventListener(
848	    'touchstart',
849	    () => {
850	      touching = true;
851	      takeOver();
852	    },
853	    { passive: true },
854	  );
855	  addEventListener(
856	    'touchend',
857	    () => {
858	      touching = false;
859	      waitToFinish();
860	    },
861	    { passive: true },
862	  );
863	  document.fonts.addEventListener('loadingdone', fit); // text changes size when its font arrives
864	  reduceMotion.addEventListener('change', applyMotion);
865	  new ResizeObserver(resize).observe(canvas);
866	  new ResizeObserver(placeEnding).observe(closeInner); // the ending's height changes with its words and fonts
867	  new ResizeObserver(fitHint).observe(wordmark); // so does the headline's
868	  new IntersectionObserver(([entry]) => {
869	    visible = entry.isIntersecting;
870	    dirty = true;
871	    schedule();
872	  }).observe(hero);
873	  applyTimeline();
874	  applyTheme();
875	})();
