// Light mode: its own footage, drawn the same way as draw() above, but centred on the precomputed box
// (LIGHT_GEOM) rather than a live edge measurement — and in both directions, since this footage's opening
// moves the book vertically too, not just side to side.
function drawLight(at) {
  const a = Math.floor(at);
  const b = Math.min(a + 1, LAST_LIGHT);
  const f = at - a;
  const fade = f > 0 && !!lightFrames[a] && !!lightFrames[b];
  const base = fade ? a : nearestLoadedLight(Math.round(at));
  if (base < 0) return false;

  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  const [aL, aR, aT, aB] = LIGHT_GEOM[a];
  const [bL, bR, bT, bB] = LIGHT_GEOM[b];
  const left = aL + (bL - aL) * f;
  const right = aR + (bR - aR) * f;
  const top = aT + (bT - aT) * f;
  const bottom = aB + (bB - aB) * f;
  const w = SRC_W_LIGHT * lightScale;
  const h = SRC_H_LIGHT * lightScale;
  const x = width / 2 - ((left + right) / 2) * lightScale;
  const y = height / 2 - ((top + bottom) / 2) * lightScale;

  ctx.globalCompositeOperation = 'source-over';
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(lightFrames[base], x, y, w, h);
  if (fade) {
    ctx.globalAlpha = f;
    ctx.drawImage(lightFrames[b], x, y, w, h);
    ctx.globalAlpha = 1;
  }
  featherEdges(x, y, w, h);

  hero.book = {
    left: x + left * lightScale,
    right: x + right * lightScale,
    top: y + top * lightScale,
    bottom: y + bottom * lightScale,
    scale: lightScale,
  };
  return true;
}

