// Picks which of the light video's 192 raw frames the site uses, measures where the book sits in each, and
// writes both into place: keep.json (read by make-light-frames.ps1, which resizes and renumbers the PNGs) and
// the LIGHT_GEOM block in site/main.js.
//
//   node videos/build-light-geom.js
//
// Why the box is measured here and not in the browser: the ivory book is barely brighter than its backdrop, so
// the live edge probe main.js uses for the dark footage (measureRight) can't find it. analyze-light-frames.js
// measured every frame offline into light-frames/report.txt; this smooths that and freezes it once the book has
// settled open, where a light sweeping over the pages moves the measurement without the book moving.

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const REPORT = path.join(__dirname, 'light-frames', 'report.txt');
const KEEP = path.join(__dirname, 'light-frames', 'keep.json');
const MAIN = path.join(root, 'site', 'main.js');

// Frames identical to the one before them: a pause in the source video, like the dark footage's 39-40.
const HELD = new Set([1, 2, 3, 4, 84, 85]);
// The book is open and still from here on; the rest of the video is a light crossing the pages. Stopping here
// keeps the scrolling spent on the opening, as the dark footage does, and drops the two glitched frames (153, 155).
const SETTLED = 131;
// Every second frame. The light take is about twice as long as the dark one for the same movement, so this
// lands near the dark footage's 87 frames, which the user signed off as smooth.
const EVERY = 2;
// The frames are resized to the dark footage's size: 184 frames of 1920x1080 is about 1.5 GB of decoded
// bitmaps, which is what made the opening stutter.
const OUT_W = 1280;
const OUT_H = 720;
const SRC_W = 1920;
const K = OUT_W / SRC_W;

const rows = [];
for (const line of fs.readFileSync(REPORT, 'utf8').split(/\r?\n/)) {
  const m = line.match(/^\s*(\d+)\s+\S+\s+\S+\s+[\d.]+\s+[\d.]+\s+[\d.]+\s+[\d.]+\s+(\d+)-(\d+)\s+(\d+)-(\d+)/);
  if (m) rows[+m[1]] = { l: +m[2], r: +m[3], t: +m[4], b: +m[5] };
}
if (rows.length !== 192) throw new Error(`Expected 192 frames in report.txt, found ${rows.length}`);

const keep = [];
const usable = [];
for (let i = 0; i <= SETTLED; i++) if (!HELD.has(i)) usable.push(i);
for (let i = 0; i < usable.length; i += EVERY) keep.push(usable[i]);

// Averaged over neighbouring frames, so the centring glides instead of stepping.
const smooth = (i, key) => {
  let sum = 0;
  let n = 0;
  for (let j = Math.max(0, i - 3); j <= Math.min(rows.length - 1, i + 3); j++) {
    if (rows[j] && !HELD.has(j)) {
      sum += rows[j][key];
      n++;
    }
  }
  return sum / n;
};

// The last few frames' own measurements already catch the start of the light sweep, so the settled box comes
// from a clean window just before it, and the last kept frames are held at it.
const REF = [115, 127];
const settled = {};
for (const key of ['l', 'r', 't', 'b']) {
  let sum = 0;
  for (let j = REF[0]; j <= REF[1]; j++) sum += rows[j][key];
  settled[key] = sum / (REF[1] - REF[0] + 1);
}

const box = (i) => {
  const b = i >= REF[0] ? settled : { l: smooth(i, 'l'), r: smooth(i, 'r'), t: smooth(i, 't'), b: smooth(i, 'b') };
  return [b.l, b.r, b.t, b.b].map((v) => Math.round(v * K));
};

const geom = keep.map(box);
const maxH = Math.max(...geom.map(([, , t, b]) => b - t));
const maxW = Math.max(...geom.map(([l, r]) => r - l));

fs.writeFileSync(KEEP, JSON.stringify({ width: OUT_W, height: OUT_H, frames: keep }, null, 1));

