  `  const LIGHT_MAX_W = ${maxW}; // widest once settled open`,
].join('\n');

const main = fs.readFileSync(MAIN, 'utf8');
const eol = main.includes('\r\n') ? '\r\n' : '\n';
const target = /  const LIGHT_GEOM = \[[\s\S]*?\];\r?\n  const LIGHT_MAX_H = .*\r?\n  const LIGHT_MAX_W = .*/;
