// Loading -----------------------------------------------------------------------

function load(i) {
  if (started.has(i)) return;
  started.add(i);
  const img = new Image();
  img.src = urls[i];
  img.decode().then(
    () => {
      frames[i] = img;
      rights[i] = measureRight(img);
      if (i >= LAST - 3) place(); // the open book's measured edge sets where the pages are
      dirty = true;
      schedule();
    },
    () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
  );
}

// First and last frames, then coarse to fine, so scrubbing works before everything arrives.
function loadAll() {
  load(0);
  load(LAST);
  for (const step of [8, 4, 2, 1]) {
    for (let i = 0; i <= LAST; i += step) load(i);
  }
}

// The light frames, fetched only once the page first turns light.
function loadLight(i) {
  if (startedLight.has(i)) return;
  startedLight.add(i);
  const img = new Image();
  img.src = urlsLight[i];
  img.decode().then(
    () => {
      lightFrames[i] = img;
      dirty = true;
      schedule();
    },
    () => console.warn(`Frame missing: ${urlsLight[i]}`),
  );
}

function loadAllLight() {
  loadLight(0);
  loadLight(LAST_LIGHT);
  for (const step of [8, 4, 2, 1]) {
    for (let i = 0; i <= LAST_LIGHT; i += step) loadLight(i);
  }
}

// Once the cover passes upright its cream lining faces the camera, so the book's right
// edge is the rightmost bright pixel along the middle row, and never less than the spine.
const probe = document.createElement('canvas');
probe.width = SRC_W;
probe.height = 1;
