const hero = document.querySelector('.hero');
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const openness = () => { const b = hero.book; return b ? +(((b.right - b.left) / (b.bottom - b.top))).toFixed(3) : null; };
const snap = () => ({ theme: document.documentElement.dataset.theme, y: scrollY, open: openness(), w: hero.book && Math.round(hero.book.right - hero.book.left), h: hero.book && Math.round(hero.book.bottom - hero.book.top), left: hero.book && Math.round(hero.book.left) });

scrollTo(0, 1200);              // part way through the opening
await wait(1500);
const before = snap();
document.querySelector('.topbar .theme').click();
await wait(2500);
const after = snap();
JSON.stringify({ before, after }, null, 1);

const slider = document.querySelector('input[aria-label="Opening glide"]');
slider.value = 0;
slider.dispatchEvent(new Event('input', { bubbles: true }));
const half = document.querySelector('input[aria-label="Auto open/close speed"]');
// Stop the page finishing the opening by itself while we look at a half-open book.
const stays = [...document.querySelectorAll('.tryout button')].find((b) => b.textContent === 'Stays');
if (stays) stays.click();
JSON.stringify({ glide: slider.value, stays: !!stays });

const hero = document.querySelector('.hero');
const canvas = document.querySelector('.hero canvas');
const st = getComputedStyle(document.querySelector('.stage'));
JSON.stringify({
  theme: document.documentElement.dataset.theme,
  scrollY, book: hero.book,
  canvas: [canvas.width, canvas.height, canvas.clientWidth, canvas.clientHeight],
  vars: { s: st.getPropertyValue('--s'), x0: st.getPropertyValue('--x0'), y0: st.getPropertyValue('--y0'), bookH: st.getPropertyValue('--book-h') },
});

const hero = document.querySelector('.hero');
const group = document.querySelector('.group');
const r = (el) => { const b = el.getBoundingClientRect(); return [Math.round(b.left), Math.round(b.right), Math.round(b.top), Math.round(b.bottom)]; };
const arabic = document.querySelector('.page.right .arabic');
JSON.stringify({
  book: hero.book && [Math.round(hero.book.left), Math.round(hero.book.right), Math.round(hero.book.top), Math.round(hero.book.bottom)],
  pageLeft: r(document.querySelector('.page.left')),
  pageRight: r(document.querySelector('.page.right')),
  arabicText: r(arabic),
  groupOpacity: group && group.style.opacity,
  groups: document.querySelectorAll('.group').length,
  arabicSnippet: arabic.textContent.slice(0, 40),
});

